/*\n  # Fix Remaining Proposal Tables RLS for Consistency\n\n  ## Summary\n  Update proposal_activity, proposal_messages, and proposal_reactivation_requests\n  to be consistent with the proposals table visibility scope.\n\n  ## Changes Made\n\n  1. **proposal_activity**\n     - SELECT: Can view if user can view the parent proposal\n     - INSERT: Can create if user can view the parent proposal\n\n  2. **proposal_messages**\n     - SELECT (Internal Staff): Can view messages for proposals they can access\n     - INSERT (Internal Staff): Can send messages for proposals they can access\n     - Keep separate policies for portal/customer access\n\n  3. **proposal_reactivation_requests**\n     - SELECT: Can view if user can view the parent proposal\n     - UPDATE: Can update if user can view the parent proposal\n\n  ## Security Notes\n  - Maintains consistent access control across all proposal-related tables\n  - Preserves portal user access for their own proposals\n*/\n\n-- =============================================\n-- PROPOSAL ACTIVITY\n-- =============================================\n\nDROP POLICY IF EXISTS "Authenticated users can view proposal activity" ON proposal_activity

\nDROP POLICY IF EXISTS "Anyone can log proposal activity" ON proposal_activity

\n\nCREATE POLICY "Users can view proposal activity"\n  ON proposal_activity\n  FOR SELECT\n  TO authenticated\n  USING (\n    EXISTS (\n      SELECT 1 FROM proposals p\n      WHERE p.id = proposal_activity.proposal_id\n        AND EXISTS (\n          SELECT 1 FROM profiles prof\n          WHERE prof.id = auth.uid()\n            AND (\n              prof.role = 'admin'\n              OR prof.proposal_visibility_scope = 'company'\n              OR (\n                prof.proposal_visibility_scope = 'office'\n                AND (p.office_id IS NULL OR p.office_id IN (\n                  SELECT office_id FROM user_offices WHERE user_id = auth.uid()\n                ))\n              )\n              OR (\n                prof.proposal_visibility_scope = 'own'\n                AND p.created_by = auth.uid()\n              )\n            )\n        )\n    )\n  )

\n\nCREATE POLICY "Users can log proposal activity"\n  ON proposal_activity\n  FOR INSERT\n  TO authenticated\n  WITH CHECK (\n    EXISTS (\n      SELECT 1 FROM proposals p\n      WHERE p.id = proposal_activity.proposal_id\n        AND EXISTS (\n          SELECT 1 FROM profiles prof\n          WHERE prof.id = auth.uid()\n            AND (\n              prof.role = 'admin'\n              OR prof.proposal_visibility_scope = 'company'\n              OR (\n                prof.proposal_visibility_scope = 'office'\n                AND (p.office_id IS NULL OR p.office_id IN (\n                  SELECT office_id FROM user_offices WHERE user_id = auth.uid()\n                ))\n              )\n              OR (\n                prof.proposal_visibility_scope = 'own'\n                AND p.created_by = auth.uid()\n              )\n            )\n        )\n    )\n  )

\n\n-- =============================================\n-- PROPOSAL MESSAGES\n-- =============================================\n\nDROP POLICY IF EXISTS "Sales reps can view all proposal messages" ON proposal_messages

\nDROP POLICY IF EXISTS "Sales reps can send messages" ON proposal_messages

\nDROP POLICY IF EXISTS "Users can mark messages as read" ON proposal_messages

\n\n-- Internal staff can view messages for proposals they have access to\nCREATE POLICY "Staff can view proposal messages"\n  ON proposal_messages\n  FOR SELECT\n  TO authenticated\n  USING (\n    EXISTS (\n      SELECT 1 FROM proposals p\n      WHERE p.id = proposal_messages.proposal_id\n        AND EXISTS (\n          SELECT 1 FROM profiles prof\n          WHERE prof.id = auth.uid()\n            AND (\n              prof.role = 'admin'\n              OR prof.proposal_visibility_scope = 'company'\n              OR (\n                prof.proposal_visibility_scope = 'office'\n                AND (p.office_id IS NULL OR p.office_id IN (\n                  SELECT office_id FROM user_offices WHERE user_id = auth.uid()\n                ))\n              )\n              OR (\n                prof.proposal_visibility_scope = 'own'\n                AND p.created_by = auth.uid()\n              )\n            )\n        )\n    )\n  )

\n\n-- Internal staff can send messages for proposals they have access to\nCREATE POLICY "Staff can send proposal messages"\n  ON proposal_messages\n  FOR INSERT\n  TO authenticated\n  WITH CHECK (\n    sender_type = 'rep'\n    AND EXISTS (\n      SELECT 1 FROM proposals p\n      WHERE p.id = proposal_messages.proposal_id\n        AND EXISTS (\n          SELECT 1 FROM profiles prof\n          WHERE prof.id = auth.uid()\n            AND (\n              prof.role = 'admin'\n              OR prof.proposal_visibility_scope = 'company'\n              OR (\n                prof.proposal_visibility_scope = 'office'\n                AND (p.office_id IS NULL OR p.office_id IN (\n                  SELECT office_id FROM user_offices WHERE user_id = auth.uid()\n                ))\n              )\n              OR (\n                prof.proposal_visibility_scope = 'own'\n                AND p.created_by = auth.uid()\n              )\n            )\n        )\n    )\n  )

\n\n-- Staff can mark messages as read for proposals they have access to\nCREATE POLICY "Staff can mark messages as read"\n  ON proposal_messages\n  FOR UPDATE\n  TO authenticated\n  USING (\n    EXISTS (\n      SELECT 1 FROM proposals p\n      WHERE p.id = proposal_messages.proposal_id\n        AND EXISTS (\n          SELECT 1 FROM profiles prof\n          WHERE prof.id = auth.uid()\n            AND (\n              prof.role = 'admin'\n              OR prof.proposal_visibility_scope = 'company'\n              OR (\n                prof.proposal_visibility_scope = 'office'\n                AND (p.office_id IS NULL OR p.office_id IN (\n                  SELECT office_id FROM user_offices WHERE user_id = auth.uid()\n                ))\n              )\n              OR (\n                prof.proposal_visibility_scope = 'own'\n                AND p.created_by = auth.uid()\n              )\n            )\n        )\n    )\n  )

\n\n-- =============================================\n-- PROPOSAL REACTIVATION REQUESTS\n-- =============================================\n\nDROP POLICY IF EXISTS "Users can view own reactivation requests" ON proposal_reactivation_requests

\nDROP POLICY IF EXISTS "Sales reps can update reactivation requests" ON proposal_reactivation_requests

\n\nCREATE POLICY "Users can view reactivation requests"\n  ON proposal_reactivation_requests\n  FOR SELECT\n  TO authenticated\n  USING (\n    EXISTS (\n      SELECT 1 FROM proposals p\n      WHERE p.id = proposal_reactivation_requests.proposal_id\n        AND EXISTS (\n          SELECT 1 FROM profiles prof\n          WHERE prof.id = auth.uid()\n            AND (\n              prof.role = 'admin'\n              OR prof.proposal_visibility_scope = 'company'\n              OR (\n                prof.proposal_visibility_scope = 'office'\n                AND (p.office_id IS NULL OR p.office_id IN (\n                  SELECT office_id FROM user_offices WHERE user_id = auth.uid()\n                ))\n              )\n              OR (\n                prof.proposal_visibility_scope = 'own'\n                AND p.created_by = auth.uid()\n              )\n            )\n        )\n    )\n  )

\n\nCREATE POLICY "Users can update reactivation requests"\n  ON proposal_reactivation_requests\n  FOR UPDATE\n  TO authenticated\n  USING (\n    EXISTS (\n      SELECT 1 FROM proposals p\n      WHERE p.id = proposal_reactivation_requests.proposal_id\n        AND EXISTS (\n          SELECT 1 FROM profiles prof\n          WHERE prof.id = auth.uid()\n            AND (\n              prof.role = 'admin'\n              OR prof.proposal_visibility_scope = 'company'\n              OR (\n                prof.proposal_visibility_scope = 'office'\n                AND (p.office_id IS NULL OR p.office_id IN (\n                  SELECT office_id FROM user_offices WHERE user_id = auth.uid()\n                ))\n              )\n              OR (\n                prof.proposal_visibility_scope = 'own'\n                AND p.created_by = auth.uid()\n              )\n            )\n        )\n    )\n  )

\n
